customEChartConfig:
{{ ((chartType) => ( 
{
  "dataset": {
    "source": [[
      "TechType",
      "Review 1",
      "Review 2",
      "Review 3"
    ]].concat(dash_appsbyTech_NV.data.reduce((acc, row) => {
      let techIndex = acc.findIndex(item => item[0] === row.techType);
      if (techIndex === -1) {
        acc.push([row.techType, 0, 0, 0]);
        techIndex = acc.length - 1;
      }
      acc[techIndex][row.reviewOrder] = row.CountOfappID;
      return acc;
    }, []))
  },
"tooltip": {
    "trigger": "axis",
    "axisPointer": {
      "type": "shadow"
    }
  },
  "legend": {
    "orient": "horizontal",
    "top": 10
  },
  "grid": {
    "left": "3%",
    "right": "4%",
    "bottom": "3%",
    "top": "15%",
    "containLabel": true
  },
  "xAxis": {
    "type": "value"
  },
  "yAxis": {
    "type": "category"
  },
  "series": [
    {
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[1] > 0 ? params.data[1] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    },
    {
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[2] > 0 ? params.data[2] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    },
    {
      "type": "bar",
      "stack": "total",
      "label": {
        "show": true,
        "position": "inside",
        "formatter": function(params) {
          return params.data[3] > 0 ? params.data[3] : '';
        }
      },
      "emphasis": {
        "focus": "series"
      }
    }
  ],
  "color": ["#5470c6", "#91cc75", "#fac858"]  // Blue, Green, Yellow
}
))(Chart8.chartType) }}
